import { ParseResult } from '../types';

/**
 * Parses QR text payload generated by ESP32 firmware:
 * Example: "Product: Smart Battery; ID: SB001; Manufacturer: ABC Electronics; Batch: B001"
 *
 * Also accommodates slight variations (newlines, alternate key names, commas, JSON).
 */
export function parseQrPayload(rawInput: string): ParseResult {
  const rawText = (rawInput || '').trim();

  if (!rawText) {
    return {
      success: false,
      missingFields: ['productName', 'productId', 'manufacturer', 'batchNumber'],
      rawText,
      error: 'Empty QR code payload.'
    };
  }

  // 1. Try parsing JSON format if payload begins with '{'
  if (rawText.startsWith('{') && rawText.endsWith('}')) {
    try {
      const parsed = JSON.parse(rawText);
      const productName = (parsed.productName || parsed.product || parsed.name || '').trim();
      const productId = (parsed.productId || parsed.id || '').trim();
      const manufacturer = (parsed.manufacturer || parsed.mfr || parsed.mfg || '').trim();
      const batchNumber = (parsed.batchNumber || parsed.batch || parsed.batchNo || '').trim();

      const missing: string[] = [];
      if (!productName) missing.push('Product Name');
      if (!productId) missing.push('Product ID');
      if (!manufacturer) missing.push('Manufacturer');
      if (!batchNumber) missing.push('Batch Number');

      if (missing.length === 0) {
        return {
          success: true,
          product: { productName, productId, manufacturer, batchNumber },
          missingFields: [],
          rawText
        };
      }
    } catch {
      // Continue to key-value parser
    }
  }

  // 2. Standard ESP32 Key-Value format (delimited by ';' or '\n' or ',')
  // We split by ';' first, or newlines if no semicolons are found
  const delimiter = rawText.includes(';') ? ';' : rawText.includes('\n') ? '\n' : ',';
  const tokens = rawText.split(delimiter);

  const extracted: Record<string, string> = {};

  for (const token of tokens) {
    const trimmed = token.trim();
    if (!trimmed) continue;

    const colonIdx = trimmed.indexOf(':');
    if (colonIdx === -1) continue;

    const key = trimmed.slice(0, colonIdx).trim().toLowerCase();
    const value = trimmed.slice(colonIdx + 1).trim();

    if (!key || !value) continue;

    // Normalize keys
    if (key === 'product' || key === 'product name' || key === 'productname' || key === 'name') {
      extracted.productName = value;
    } else if (key === 'id' || key === 'product id' || key === 'productid') {
      extracted.productId = value;
    } else if (key === 'manufacturer' || key === 'mfr' || key === 'mfg' || key === 'manufacture') {
      extracted.manufacturer = value;
    } else if (key === 'batch' || key === 'batch number' || key === 'batch no' || key === 'batchno' || key === 'batchnumber') {
      extracted.batchNumber = value;
    }
  }

  const missingFields: string[] = [];
  if (!extracted.productName) missingFields.push('Product Name');
  if (!extracted.productId) missingFields.push('Product ID');
  if (!extracted.manufacturer) missingFields.push('Manufacturer');
  if (!extracted.batchNumber) missingFields.push('Batch Number');

  if (missingFields.length > 0) {
    return {
      success: false,
      missingFields,
      rawText,
      error: `Missing required field(s): ${missingFields.join(', ')}`
    };
  }

  return {
    success: true,
    product: {
      productName: extracted.productName,
      productId: extracted.productId,
      manufacturer: extracted.manufacturer,
      batchNumber: extracted.batchNumber
    },
    missingFields: [],
    rawText
  };
}

/**
 * Formats a ProductRecord into the standard ESP32 QR text format
 */
export function formatEsp32Payload(product: {
  productName: string;
  productId: string;
  manufacturer: string;
  batchNumber: string;
}): string {
  return `Product: ${product.productName.trim()}; ID: ${product.productId.trim()}; Manufacturer: ${product.manufacturer.trim()}; Batch: ${product.batchNumber.trim()}`;
}
